-- 002_core_schema.sql
-- Esquema base migrado desde MariaDB 10.4.32 (sport.sql).
-- Conversiones:
--   int AUTO_INCREMENT      -> integer GENERATED BY DEFAULT AS IDENTITY (permite importar ids existentes)
--   ENUM(...)               -> text + CHECK (col IN (...))
--   tinyint(1)              -> boolean
--   timestamp               -> timestamptz
--   ON UPDATE current_ts    -> trigger set_updated_at()
--   UNIQUE email (ci)       -> UNIQUE (lower(email)) (MariaDB comparaba sin distinguir mayúsculas)

-- ---------------------------------------------------------------- Catálogo

CREATE TABLE product_categories (
  category_id   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          text CHECK (name IN ('energia','hidratacion','recuperacion','vitaminas')),
  description   text,
  usage_context text CHECK (usage_context IN ('pre entrenamiento','durante entrenamiento','post entrenamiento','diario'))
);

CREATE TABLE product_types (
  type_id     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  category_id integer REFERENCES product_categories (category_id),
  name        varchar(50) NOT NULL,
  description text
);
CREATE INDEX product_types_category_id_idx ON product_types (category_id);

CREATE TABLE products (
  product_id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  type_id              integer REFERENCES product_types (type_id),
  name                 varchar(100) NOT NULL,
  description          text,
  image_url            varchar(255),
  usage_recommendation text,
  is_active            boolean DEFAULT true
);
CREATE INDEX products_type_id_idx ON products (type_id);

CREATE TABLE product_attributes (
  attribute_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name         text CHECK (name IN ('vegetariano','vegano','libre de gluten','libre de lactosa','libre de trigo',
                                    'libre de frutos secos','libre de soya','con cafeina','isotonico',
                                    'alto en carbohidrato','alto en proteina')),
  description  text
);

CREATE TABLE product_attributes_mapping (
  product_id   integer NOT NULL REFERENCES products (product_id),
  attribute_id integer NOT NULL REFERENCES product_attributes (attribute_id),
  PRIMARY KEY (product_id, attribute_id)
);
CREATE INDEX product_attributes_mapping_attribute_id_idx ON product_attributes_mapping (attribute_id);

CREATE TABLE flavors (
  flavor_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name      varchar(50) NOT NULL
);

CREATE TABLE product_flavors (
  product_id integer NOT NULL REFERENCES products (product_id),
  flavor_id  integer NOT NULL REFERENCES flavors (flavor_id),
  PRIMARY KEY (product_id, flavor_id)
);
CREATE INDEX product_flavors_flavor_id_idx ON product_flavors (flavor_id);

CREATE TABLE product_nutrition (
  nutrition_id     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id       integer REFERENCES products (product_id),
  serving_size     varchar(50),
  energy_kcal      numeric(10,2),
  protein_g        numeric(10,2),
  carbs_g          numeric(10,2),
  sugars_g         numeric(10,2),
  sodium_mg        numeric(10,2),
  potassium_mg     numeric(10,2) NOT NULL DEFAULT 0,
  magnesium_mg     numeric(10,2) NOT NULL DEFAULT 0,
  caffeine_mg      numeric(10,2),
  other_components text NOT NULL DEFAULT 'None'
);
CREATE INDEX product_nutrition_product_id_idx ON product_nutrition (product_id);

-- ---------------------------------------------------------------- Usuarios

CREATE TABLE users (
  user_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username   varchar(255) NOT NULL,
  email      varchar(255) NOT NULL,
  password   varchar(255) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_email_lower_key ON users (lower(email));

CREATE TABLE user_profiles (
  profile_id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id              integer NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  age                  integer,
  weight               numeric(5,2),
  height               numeric(5,2),
  gender               text CHECK (gender IN ('hombre','mujer','otro','prefiero no decir')),
  activity_level       text DEFAULT 'moderado' CHECK (activity_level IN ('sedentario','moderado','activo','muy activo')),
  training_frequency   text CHECK (training_frequency IN ('1-2','3-4','5+','ocasional')),
  primary_goal         text CHECK (primary_goal IN ('mejor rendimiento','perder peso','ganar musculo','resistencia','recuperacion','por salud')),
  sweat_level          text CHECK (sweat_level IN ('bajo','medio','alto')),
  caffeine_tolerance   text CHECK (caffeine_tolerance IN ('no','bajo','medio','alto')),
  dietary_restrictions text DEFAULT 'no' CHECK (dietary_restrictions IN ('vegetariano','vegano','libre de gluten','libre de lactosa','libre de frutos secos','no'))
);
CREATE INDEX user_profiles_user_id_idx ON user_profiles (user_id);

CREATE TABLE notification_preferences (
  user_id               integer PRIMARY KEY REFERENCES users (user_id) ON DELETE CASCADE,
  consumption_reminders boolean DEFAULT true,
  training_alerts       boolean DEFAULT true,
  preferred_time        time DEFAULT '09:00:00',
  updated_at            timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER notification_preferences_set_updated_at
  BEFORE UPDATE ON notification_preferences
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE training_sessions (
  session_id   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id      integer NOT NULL REFERENCES users (user_id),
  session_date date NOT NULL,
  start_time   time,
  duration_min integer NOT NULL,
  intensity    text CHECK (intensity IN ('bajo','medio','alto','muy alto')),
  type         text CHECK (type IN ('cardio','fuerza','hiit','resistencia','mixed','otro')),
  weather      text CHECK (weather IN ('frio','fresco','moderado','calido','caliente','humedo')),
  sport_type   text CHECK (sport_type IN ('10K','15K','ciclismo de ruta','ciclismo de montaña','marathon',
                                          'media marathon','trail','Triathlon','natacion')),
  notes        text
);
CREATE INDEX training_sessions_user_id_idx ON training_sessions (user_id);

CREATE TABLE recommendations (
  recommendation_id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id                  integer NOT NULL REFERENCES users (user_id),
  session_id               integer REFERENCES training_sessions (session_id),
  product_id               integer NOT NULL REFERENCES products (product_id),
  recommended_at           timestamptz NOT NULL DEFAULT now(),
  feedback                 text CHECK (feedback IN ('positivo','neutral','negativo')),
  feedback_notes           text,
  consumption_timing       text CHECK (consumption_timing IN ('antes','durante','despues','diario')),
  consumption_instructions text,
  recommended_quantity     varchar(100),
  timing_minutes           integer
);
COMMENT ON COLUMN recommendations.timing_minutes IS 'Minutos antes/después del entrenamiento';
CREATE INDEX recommendations_user_id_idx ON recommendations (user_id);
CREATE INDEX recommendations_session_id_idx ON recommendations (session_id);
CREATE INDEX recommendations_product_id_idx ON recommendations (product_id);
CREATE INDEX idx_rec_user_date ON recommendations (user_id, recommended_at);
CREATE INDEX idx_rec_user_product ON recommendations (user_id, product_id);

CREATE TABLE user_product_feedback (
  feedback_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id     integer NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  product_id  integer NOT NULL REFERENCES products (product_id) ON DELETE CASCADE,
  feedback    text NOT NULL CHECK (feedback IN ('positivo','negativo')),
  notes       text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz,
  CONSTRAINT unique_user_product UNIQUE (user_id, product_id)
);
CREATE INDEX idx_user_feedback ON user_product_feedback (user_id, feedback);
CREATE INDEX idx_product_feedback ON user_product_feedback (product_id, feedback);
CREATE TRIGGER user_product_feedback_set_updated_at
  BEFORE UPDATE ON user_product_feedback
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
